export type createReminderResponse202 = {
  data: void;
  status: 202;
};

export type createReminderResponse422 = {
  data: UnprocessableResponse;
  status: 422;
};

export type createReminderResponse429 = {
  data: TooManyRequestsResponse;
  status: 429;
};

export type createReminderResponseSuccess = createReminderResponse202 & {
  headers: Headers;
};
export type createReminderResponseError = (
  createReminderResponse422 | createReminderResponse429
) & {
  headers: Headers;
};

export type createReminderResponse =
  createReminderResponseSuccess | createReminderResponseError;

export const getCreateReminderUrl = () => {
  return `/reminders`;
};

/**
 * Rate limit 1 per (sender, recipient) per 60 seconds. The server does not check that the recipient owes the sender.
 * @summary Email a settle-up reminder to someone who owes you (V2)
 */
export const createReminder = async (
  reminderCreate: ReminderCreate,
  options?: Parameters<typeof customFetch>[1],
): Promise<createReminderResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit['headers']>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          entry => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<createReminderResponse>(getCreateReminderUrl(), {
    ...options,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(reminderCreate),
  });
};

export const getCreateReminderMutationKey = () => ['createReminder'] as const;

export const getCreateReminderMutationOptions = <
  TError = UnprocessableResponse | TooManyRequestsResponse,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createReminder>>,
    TError,
    CreateReminderMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createReminder>>,
  TError,
  CreateReminderMutationVariables,
  TContext
> => {
  const mutationKey = getCreateReminderMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      'mutationKey' in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createReminder>>,
    CreateReminderMutationVariables
  > = props => {
    const { data } = props ?? {};

    return createReminder(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CreateReminderMutationResult = NonNullable<
  Awaited<ReturnType<typeof createReminder>>
>;
export type CreateReminderMutationBody = ReminderCreate;
export type CreateReminderMutationError =
  UnprocessableResponse | TooManyRequestsResponse;
export type CreateReminderMutationVariables = { data: ReminderCreate };

/**
 * @summary Email a settle-up reminder to someone who owes you (V2)
 */
export const useCreateReminder = <
  TError = UnprocessableResponse | TooManyRequestsResponse,
  TContext = unknown,
>(
  options?: {
    mutation?: UseMutationOptions<
      Awaited<ReturnType<typeof createReminder>>,
      TError,
      CreateReminderMutationVariables,
      TContext
    >;
    request?: SecondParameter<typeof customFetch>;
  },
  queryClient?: QueryClient,
): UseMutationResult<
  Awaited<ReturnType<typeof createReminder>>,
  TError,
  CreateReminderMutationVariables,
  TContext
> => {
  return useMutation(getCreateReminderMutationOptions(options), queryClient);
};

